// Modèle de supervision du vérin VR-01.
// Table Modbus : voir src/tp_simu_auto/modbus_map.py
//
// Entrées (msg.topic) :
//   'coils' / 'di' / 'ir' / 'hr' : lectures cycliques de l'automate
//   'tick'                       : horloge 1 s (surveillance de la communication)
//   'ihm'                        : action opérateur, msg.payload = { action, ... }
// Sorties : [état complet pour l'écran, écritures Modbus (modbus-flex-write)]

const UNIT_ID = 1;
const TIMEOUT_COMM_MS = 1000;
const TAILLE_JOURNAL = 100;

const COIL = { DEPART: 0, ARRET: 1, MANUEL: 2, JOG_SORTIE: 3, JOG_RENTREE: 4, AU: 5, REARMEMENT: 6, SIMU_BLOCAGE: 7, SIMU_PRESSION: 8 };
const DI = { Y1: 0, Y2: 1, B1: 2, B2: 3, CYCLE: 4, DEFAUT: 5, ARRET_FIN_CYCLE: 6 };
const IR = { POSITION: 0, ETAPE: 1, DEFAUTS: 2, CYCLES: 3, DUREE_SORTIE: 4, DUREE_RENTREE: 5 };
const ETAPES = ['Repos', 'Sortie', 'Tempo haut', 'Rentrée', 'Manuel', 'Défaut'];
const DEFAUTS = [
    { bit: 1, code: 'AU', texte: 'Arrêt d\'urgence enclenché' },
    { bit: 2, code: 'TO_SORTIE', texte: 'Défaut sortie : capteur B2 non atteint dans le temps imparti' },
    { bit: 4, code: 'TO_RENTREE', texte: 'Défaut rentrée : capteur B1 non atteint dans le temps imparti' },
    { bit: 8, code: 'BLOCAGE', texte: 'Vérin bloqué : aucun mouvement malgré la commande' }
];

const now = Date.now();
const st = context.get('st') || {
    coils: null, di: null, ir: null, hr: null,
    derniereLecture: now,       // délai de grâce au démarrage
    commPrec: null,
    sens: 'descente',
    prec: null,
    alarmes: [],
    journal: [],
    seq: 0
};

function journaliser(type, texte) {
    st.journal.unshift({ t: now, type, texte });
    if (st.journal.length > TAILLE_JOURNAL) st.journal.length = TAILLE_JOURNAL;
}

// Une alarme apparaît quand sa condition devient vraie et reste affichée tant
// qu'elle est active ou non acquittée.
function alarme(code, texte, condition) {
    const active = st.alarmes.find(a => a.code === code && a.active);
    if (condition && !active) {
        st.alarmes.unshift({ id: ++st.seq, code, texte, t: now, active: true, acquittee: false });
        journaliser('alarme', texte);
    } else if (!condition && active) {
        active.active = false;
        journaliser('info', 'Disparition : ' + texte);
        // Une alarme disparue et déjà acquittée quitte la liste
        if (active.acquittee) st.alarmes = st.alarmes.filter(a => a !== active);
    }
}

const ecritures = [];
function ecrireCoil(adresse, valeur) {
    ecritures.push({ payload: { value: valeur, fc: 5, unitid: UNIT_ID, address: adresse, quantity: 1 } });
}

let emettre = true;

switch (msg.topic) {
    case 'coils': st.coils = msg.payload; emettre = false; break;
    case 'di': st.di = msg.payload; emettre = false; break;
    case 'hr': st.hr = msg.payload; emettre = false; break;
    case 'ir':
        st.ir = msg.payload;
        st.derniereLecture = now;
        break;
    case 'ihm': {
        const a = msg.payload || {};
        emettre = false;
        switch (a.action) {
            case 'depart':
                ecrireCoil(COIL.DEPART, true);
                journaliser('operateur', 'Départ cycle demandé');
                break;
            case 'arret':
                ecrireCoil(COIL.ARRET, true);
                journaliser('operateur', 'Arrêt en fin de cycle demandé');
                break;
            case 'mode':
                ecrireCoil(COIL.JOG_SORTIE, false);
                ecrireCoil(COIL.JOG_RENTREE, false);
                ecrireCoil(COIL.MANUEL, a.manuel === true);
                journaliser('operateur', 'Passage en mode ' + (a.manuel ? 'MANUEL' : 'AUTOMATIQUE'));
                break;
            case 'jog':
                ecrireCoil(a.sens === 'sortie' ? COIL.JOG_SORTIE : COIL.JOG_RENTREE, a.actif === true);
                break;
            case 'au':
                ecrireCoil(COIL.AU, a.actif === true);
                journaliser(a.actif ? 'alarme' : 'operateur', a.actif ? 'Arrêt d\'urgence actionné' : 'Arrêt d\'urgence déverrouillé');
                break;
            case 'acquitter':
                st.alarmes.forEach(x => { x.acquittee = true; });
                st.alarmes = st.alarmes.filter(x => x.active);
                ecrireCoil(COIL.REARMEMENT, true);
                journaliser('operateur', 'Acquittement et réarmement des défauts');
                emettre = true;
                break;
            case 'simu':
                ecrireCoil(a.defaut === 'blocage' ? COIL.SIMU_BLOCAGE : COIL.SIMU_PRESSION, a.actif === true);
                journaliser('simulation', (a.actif ? 'Activation' : 'Désactivation') + ' de la simulation : '
                    + (a.defaut === 'blocage' ? 'blocage mécanique' : 'pression d\'air basse'));
                break;
            case 'parametres': {
                const v = [a.tempoHaut, a.timeoutSortie, a.timeoutRentree].map(x => Math.round(Number(x) * 10));
                if (v.some(x => !Number.isFinite(x) || x < 0 || x > 6000)) break;
                ecritures.push({ payload: { value: v, fc: 16, unitid: UNIT_ID, address: 0, quantity: 3 } });
                journaliser('operateur', 'Paramètres modifiés : tempo haut ' + a.tempoHaut + ' s, timeout sortie '
                    + a.timeoutSortie + ' s, timeout rentrée ' + a.timeoutRentree + ' s');
                break;
            }
        }
        break;
    }
}

// --- Communication ---
const comm = now - st.derniereLecture < TIMEOUT_COMM_MS && st.ir !== null;
if (st.commPrec === false && comm) journaliser('info', 'Communication automate rétablie');
st.commPrec = comm;
alarme('COMM', 'Perte de communication avec l\'automate', !comm && now - (context.get('demarrage') || now) > 2000);
if (!context.get('demarrage')) context.set('demarrage', now);

// --- État de l'automate ---
const c = st.coils || [], d = st.di || [], r = st.ir || [], h = st.hr || [];
const etat = {
    position: (r[IR.POSITION] || 0) / 10,
    etape: r[IR.ETAPE] || 0,
    defauts: r[IR.DEFAUTS] || 0,
    cycles: r[IR.CYCLES] || 0,
    dureeSortie: r[IR.DUREE_SORTIE] ? r[IR.DUREE_SORTIE] / 10 : null,
    dureeRentree: r[IR.DUREE_RENTREE] ? r[IR.DUREE_RENTREE] / 10 : null,
    y1: d[DI.Y1] === true, y2: d[DI.Y2] === true,
    b1: d[DI.B1] === true, b2: d[DI.B2] === true,
    cycleEnCours: d[DI.CYCLE] === true,
    arretFinCycle: d[DI.ARRET_FIN_CYCLE] === true,
    manuel: c[COIL.MANUEL] === true,
    au: c[COIL.AU] === true,
    jogSortie: c[COIL.JOG_SORTIE] === true,
    jogRentree: c[COIL.JOG_RENTREE] === true,
    simuBlocage: c[COIL.SIMU_BLOCAGE] === true,
    simuPression: c[COIL.SIMU_PRESSION] === true,
    parametres: h.length >= 3 ? { tempoHaut: h[0] / 10, timeoutSortie: h[1] / 10, timeoutRentree: h[2] / 10 } : null
};

if (etat.y1) st.sens = 'montee';
else if (etat.y2) st.sens = 'descente';

// Alarmes issues du mot de défauts de l'automate (mémorisées jusqu'au réarmement)
if (comm) {
    for (const def of DEFAUTS) alarme(def.code, def.texte, (etat.defauts & def.bit) !== 0);

    // Journal des changements d'état significatifs
    const p = st.prec;
    if (p) {
        if (etat.manuel !== p.manuel) journaliser('info', 'Automate en mode ' + (etat.manuel ? 'MANUEL' : 'AUTOMATIQUE'));
        if (etat.cycleEnCours && !p.cycleEnCours) journaliser('info', 'Cycle automatique démarré');
        if (!etat.cycleEnCours && p.cycleEnCours) journaliser('info', d[DI.DEFAUT] === true ? 'Cycle interrompu par un défaut' : 'Cycle automatique terminé, vérin au repos');
        if (etat.defauts === 0 && p.defauts !== 0) journaliser('info', 'Automate réarmé, défauts effacés');
    }
    st.prec = { manuel: etat.manuel, cycleEnCours: etat.cycleEnCours, defauts: etat.defauts };
}

context.set('st', st);

let etatMachine;
if (!comm) etatMachine = { code: 'hors-ligne', texte: 'HORS LIGNE' };
else if (etat.au) etatMachine = { code: 'au', texte: 'ARRÊT D\'URGENCE' };
else if (etat.defauts) etatMachine = { code: 'defaut', texte: 'EN DÉFAUT' };
else if (etat.manuel) etatMachine = { code: 'manuel', texte: 'MANUEL' };
else if (etat.cycleEnCours) etatMachine = { code: 'cycle', texte: 'EN CYCLE' };
else etatMachine = { code: 'arret', texte: 'À L\'ARRÊT' };

const sortieIhm = !emettre ? null : {
    payload: Object.assign(etat, {
        t: now,
        comm,
        sens: st.sens,
        fin: etat.b2 ? 'max' : (etat.b1 ? 'min' : null),
        nomEtape: ETAPES[etat.etape] || '?',
        etatMachine,
        alarmes: st.alarmes.slice(0, 30),
        journal: st.journal.slice(0, 60)
    })
};

return [sortieIhm, ecritures.length ? ecritures : null];
